 95 function instrumentServer(server, report) {
 96   // 在真实 HTTP 处理器的 IncomingMessage/ServerResponse 上记录。
 97   // 只记录流字节和 finish/abort，不另行响应请求。
 98   server.prependListener('request', (request, response) => {
 99     const entry = {id: report.service.length + 1, receivedAt: now(),
100       method: request.method, url: request.url, headers: request.headers,
101       rawHeaders: request.rawHeaders, httpVersion: request.httpVersion};
102     report.service.push(entry);
103     const requestChunks = [], responseChunks = [];
104     request.on('data', chunk => requestChunks.push(Buffer.from(chunk)));
105     const saveRequest = () => {
106       const bytes = Buffer.concat(requestChunks);
107       entry.requestBody = bytes.toString('utf8');
108       entry.requestBase64 = bytes.toString('base64');
109     };
110     request.on('end', () => { saveRequest(); entry.requestEndedAt = now(); });
111     request.on('aborted', () => { saveRequest(); entry.abortedAt = now(); });
112     request.on('error', error => { entry.requestError = errorRecord(error); });
113     const remember = (chunk, encoding) => {
114       if (chunk !== undefined && chunk !== null && typeof chunk !== 'function') {
115         responseChunks.push(Buffer.isBuffer(chunk) ? Buffer.from(chunk)
116           : Buffer.from(chunk, typeof encoding === 'string' ? encoding : undefined));
117       }
118     };
119     const originalWrite = response.write, originalEnd = response.end;
120     response.write = function(chunk, encoding, callback) {
121       remember(chunk, encoding);
122       return originalWrite.call(this, chunk, encoding, callback);
123     };
124     response.end = function(chunk, encoding, callback) {
125       remember(chunk, encoding);
126       return originalEnd.call(this, chunk, encoding, callback);
127     };
128     const saveResponse = () => {
129       const bytes = Buffer.concat(responseChunks);
130       entry.response = {status: response.statusCode, headers: response.getHeaders(),
131         body: bytes.toString('utf8'), base64: bytes.toString('base64'),
132         writableFinished: response.writableFinished};
133     };
134     response.on('finish', () => { saveResponse(); entry.finishedAt = now(); });
135     response.on('close', () => { saveRequest(); saveResponse(); entry.closedAt = now(); });
136     response.on('error', error => { entry.responseError = errorRecord(error); });
137   });
138   server.on('error', error => report.environmentErrors.push({kind: 'HTTP', error: errorRecord(error)}));
139 }
140 function instrumentPage(page, report, captures) {
141   const requests = new WeakMap();
142   page.on('request', request => {
143     const entry = {id: report.browserNetwork.length + 1, at: now(),
144       method: request.method(), url: request.url(), resourceType: request.resourceType(),
145       headers: request.headers(), body: request.postData(),
146       bodyBase64: request.postDataBuffer()?.toString('base64') ?? null};
147     requests.set(request, entry);
148     report.browserNetwork.push(entry);
149   });
150   page.on('response', response => {
151     const job = (async () => {
152       const entry = requests.get(response.request());
153       if (!entry) throw new Error('响应没有对应的请求记录');
154       entry.response = {at: now(), url: response.url(), status: response.status(),
155         headers: await response.allHeaders()};
156       const bytes = await response.body();
157       entry.response.body = bytes.toString('utf8');
158       entry.response.base64 = bytes.toString('base64');
159       entry.response.completedAt = now();
160     })().catch(error => report.recordingErrors.push({kind: 'response', error: errorRecord(error)}));
161     captures.add(job);
162     void job.finally(() => captures.delete(job));
163   });
164   page.on('requestfailed', request => {
165     const entry = requests.get(request);
166     if (entry) entry.failed = {at: now(), ...request.failure()};
167   });
168   page.on('pageerror', error => report.pageErrors.push(errorRecord(error)));
169   page.on('console', message => report.console.push({at: now(), type: message.type(), text: message.text()}));
170   page.on('dialog', dialog => {
171     report.dialogs.push({at: now(), type: dialog.type(), message: dialog.message(), action: 'accept'});
172     // 刷新时确认离开带有本地编辑的页面，不保存这些编辑。
173     const job = dialog.accept().catch(error => report.recordingErrors.push({kind: 'dialog', error: errorRecord(error)}));
174     captures.add(job);
