469 async function runScenario(scenario) {
470   const id = randomUUID(), directory = resolve(project, 'runs', `regression-${id}`);
471   const database = resolve(directory, 'practice.sqlite'), recordPath = resolve(directory, 'record.json');
472   const report = {kind: 'saving_regression_observation', id, scenario, startedAt: now(),
473     directory, database, recordPath,
474     scope: '完整三章来自既有课堂存档；本次seed为新作品human/draft r1。程序检查不表示文学采用。历史恢复点只用于独立红绿对照；正确工作台在另一个冻结副本。',
475     limits: ['每场景一个工作台、一次保存尝试，无布局循环和自动重试。',
476       'abort仅发生在服务收到请求前，不覆盖服务提交后断网、撤销或回滚。',
477       '未覆盖GET失败、未知终态、并发写入、所有空白字符及页面审美。'],
478     environment: {cwd: process.cwd(), project, node: process.version, platform: process.platform,
479       arch: process.arch, deliveryBrowserChannel: process.env.DELIVERY_BROWSER_CHANNEL ?? null,
480       waitLimitsMs: {action: ACTION_LIMIT, request: LIMIT, step: STEP_LIMIT,
481         observations: OBSERVATION_LIMIT, nodeTest: TEST_LIMIT}},
482     sources: {}, pages: [], databases: [], service: [], browserNetwork: [], gates: [],
483     console: [], dialogs: [], pageErrors: [], assertions: [], completed: [],
484     environmentErrors: [], observationErrors: [], recordingErrors: [], cleanupErrors: [], cleanup: [], sourceChanges: []};
485   let store, server, browser, context, page, seedModule, input, expectation, A, finalDb;
486   const observed = {}, captures = new Set(), routeTasks = new Set();
487   const observationDeadline = Date.now() + OBSERVATION_LIMIT;
488   const postGate = makeGate('post', report), getGate = makeGate('get', report);
489   let postUsed = false, getUsed = false, saveReadArmed = false;
490   function persist(label) {
491     report.lastCheckpoint = {label, at: now()};
492     report.unfinished = planned[scenario].filter(step => !report.completed.includes(step));
493     try {
494       writeFileSync(recordPath, JSON.stringify(report, null, 2) + '\n', 'utf8');
495       return true;
496     }
497     catch (error) {
498       report.recordingErrors.push({kind: 'write', label, recordPath, error: errorRecord(error)});
499       process.stderr.write(`记录写入失败：${recordPath}：${error.message}\n`);
500       return false;
501     }
502   }
503   async function step(name, action) {
504     report.activeStep = name;
505     const remaining = observationDeadline - Date.now();
506     if (remaining <= 0) throw new Error('观察时间已用完，开始清理并记录最终状态。');
507     observed[name] = await bounded(Promise.resolve().then(action), `observation/${name}`, Math.min(STEP_LIMIT, remaining));
508     report.completed.push(name);
509     report.observed = observed;
510     persist(name);
511     return observed[name];
512   }
513   async function cleanup(name, action) {
514     const entry = {name, startedAt: now()};
515     report.cleanup.push(entry);
516     try { await bounded(Promise.resolve().then(action), `cleanup/${name}`); entry.completedAt = now(); }
517     catch (error) { report.cleanupErrors.push({name, error: errorRecord(error)}); }
518   }
519   const draftMatch = url => url.pathname === '/api/draft';
520   const workMatch = url => url.pathname === '/api/work';

521   const trackedRoute = action => route => {
522     const job = action(route).catch(error => report.observationErrors.push({step: 'route', error: errorRecord(error)}));
523     routeTasks.add(job);
524     void job.finally(() => routeTasks.delete(job));
525     return job;
526   };
527   const draftHandler = trackedRoute(async route => {
528     if (route.request().method() !== 'POST' || postUsed) { await route.continue(); return; }
529     postUsed = true;
530     postGate.arrive(route.request());
