657         await page.waitForFunction(() => document.getElementById('message').dataset.kind === 'error' &&
658           !document.getElementById('reload').disabled, undefined, {timeout: LIMIT});
659         databaseState(store, seedModule.snapshot, input.work.id, report, 'after service-before abort');
660         return pageState(page, report, 'abort complete A retained');
661       });
662       await step('afterKeyboard', () => attemptPair(page, report, 'abort before recovery read', expectation.edits.after));
663       await step('recoveryRead', async () => {
664         await page.getByRole('button', {name: '读取当前稿', exact: true}).click();
665         await page.waitForFunction(() => !document.getElementById('reload').disabled &&
666           document.getElementById('message').textContent.includes('已读回'), undefined, {timeout: LIMIT});
667         return pageState(page, report, 'abort read-current restores save permission');
668       });
669     }
670     await bounded(Promise.all([...captures]), 'complete response recording');
671     finalDb = databaseState(store, seedModule.snapshot, input.work.id, report, 'observations complete');
672     persist('observations complete; business assertions not yet evaluated');
673   } catch (error) {
674     const errors = report.activeStep ? report.observationErrors : report.environmentErrors;
675     errors.push({step: report.activeStep ?? 'setup', error: errorRecord(error)});
676   } finally {
677     // 观察失败后也放行两个门，清理可能完成仍在等待的真实保存。
678     // 因此清理后再次完整记录数据库。
679     postGate.open('finally release');
680     getGate.open('finally release');
681     if (page) {
682       await cleanup('route handlers settle', () => Promise.all([...routeTasks]));
683       await cleanup('routes removed', () => page.unrouteAll({behavior: 'wait'}));
684       await cleanup('response records drained', () => Promise.all([...captures]));
685       await cleanup('page closed without saving local edits', () => page.close({runBeforeUnload: false}));
686     }
687     if (context) await cleanup('browser context closed', () => context.close());
688     if (browser) await cleanup('browser closed', () => browser.close());
689     if (server) await cleanup('HTTP closed', () => new Promise((resolveClose, reject) => {
690       if (!server.listening) { server.closeAllConnections(); resolveClose(); return; }
691       server.close(error => error ? reject(error) : resolveClose());
692       server.closeAllConnections();
693     }));
694     if (store) {
695       await cleanup('final five tables and history captured', () => {
696         finalDb = databaseState(store, seedModule.snapshot, input.work.id, report, 'after cleanup before Store close');
697       });
698       await cleanup('Store closed', () => store.close());
699     }
700     await cleanup('response records final drain', () => Promise.all([...captures]));
701     for (const [path, source] of Object.entries(report.sources)) {
702       if (source.error) continue;
703       try {
704         const actual = sha256(readFileSync(resolve(project, path)));
705         if (actual !== source.sha256) report.sourceChanges.push({path, before: source.sha256, after: actual});
706       } catch (error) { report.recordingErrors.push({kind: 'source reread', path, error: errorRecord(error)}); }
707     }
708     report.environment.gitAfter = gitState(directory);
709     report.observed = observed;
710     report.unfinished = planned[scenario].filter(step => !report.completed.includes(step));
711     if (scenario === 'normal') {
712       report.waitingInputObservation = ['post', 'get'].map(phase => ({phase,
713         fullValueBefore: observed[`${phase}Keyboard`]?.fields.title.before && pair(observed[`${phase}Keyboard`].fields.title.before),
714         fullValueAfter: observed[`${phase}Keyboard`]?.after && pair(observed[`${phase}Keyboard`].after),
715         attemptedText: expectation?.edits?.[phase]}));
716       report.readbackReplacement = {
717         before: observed.getKeyboard?.after && pair(observed.getKeyboard.after),
718         after: observed.readback && pair(observed.readback)};
719     }
720     try { assertBusiness(report, observed, input, expectation, A, finalDb); }
721     catch (error) { report.assertions.push({name: 'assertion collection completed', passed: false, error: errorRecord(error)}); }
722     report.finishedAt = now();
723     report.passed = report.assertions.every(item => item.passed) &&
724       !report.observationErrors.length && !report.environmentErrors.length &&
725       !report.recordingErrors.length && !report.cleanupErrors.length;
726     if (!persist('final')) {
727       report.passed = false;
728       // 记录写入失败时，将完整诊断留在 stderr 并报失败。
729       // 不重试，也不把未落盘记录报作成功。
730       process.stderr.write(JSON.stringify(report, null, 2) + '\n');
731     }
732     if (report.recordingErrors.length) report.passed = false;
733     process.stdout.write(`${scenario}: ${report.passed ? 'PASS' : 'FAIL'}；完整记录：${recordPath}\n`);
734   }
735   const failures = report.assertions.filter(item => !item.passed).map(item => item.name);
736   assert.equal(report.passed, true, `${scenario} 失败：${failures.join('; ')}；完整记录：${recordPath}`);
737 }
738 
739 // 两个独立用例顺序运行，历史正常保存失败后仍执行 abort 观察。
740 // 每例都单独初始化完整三章。
741 await test('正常保存：完整A、POST等待、GET读回等待、恢复编辑及刷新历史',
742   {concurrency: false, timeout: TEST_LIMIT}, () => runScenario('normal'));
743 await test('服务收到POST前abort：无服务POST/新增修订，保留A并先读当前稿',
744   {concurrency: false, timeout: TEST_LIMIT}, () => runScenario('abort'));

