611     await step('before', () => attemptPair(page, report, 'before', expectation.edits.before));
612     await step('comparison', async () => {
613       await page.getByRole('button', {name: '重新读取', exact: true}).click();
614       await page.waitForFunction(() => !document.getElementById('comparison').hidden &&
