619     await step('gatesInstalled', async () => {
620       await page.route(draftMatch, draftHandler);
621       await page.route(workMatch, workHandler);
622       return {at: now(), after: 'initial read, chapter selection, existing comparison', responseMocking: false};
623     });
624     await page.getByRole('button', {name: '保存草稿', exact: true}).click();
625     await bounded(postGate.hit.promise, 'POST gate arrival');
626     if (scenario === 'normal') {
627       await step('postWait', async () => ({page: await pageState(page, report, 'POST gated'),
628         servicePostCount: postRequests(report).length,
629         database: databaseState(store, seedModule.snapshot, input.work.id, report, 'POST gated')}));
630       await step('postKeyboard', () => attemptPair(page, report, 'post', expectation.edits.post));
631       postGate.open('finished POST-wait keyboard observations');
632       await bounded(getGate.hit.promise, 'save-read GET gate arrival');
633       await step('getWait', async () => ({page: await pageState(page, report, 'GET gated'),
