  80   private persistChapter(chapter:Chapter):Chapter{
  81     const content=JSON.stringify(chapter);
  82     this.db.prepare('INSERT INTO chapters VALUES(?,?,?,?) ON CONFLICT(work_id,number) DO UPDATE SET revision=excluded.revision,content=excluded.content').run(chapter.workId,chapter.number,chapter.revision,content);
  83     this.db.prepare('INSERT INTO chapter_versions VALUES(?,?,?,?)').run(chapter.workId,chapter.number,chapter.revision,content);
  84     return chapter;
  85   }
  86   listChapters(workId:string):Omit<Chapter,'body'>[]{
  87     this.getWork(workId);
  88     const rows=this.db.prepare('SELECT content FROM chapters WHERE work_id=? ORDER BY number').all(workId);
  89     return rows.map(row=>{const {body,...chapter}=JSON.parse(row.content as string) as Chapter;return chapter;});
  90   }
  91   saveDraft(input:DraftInput,origin:'human'|'agent',taskId:string|null=null):Chapter{
  92     return this.transaction(()=>{
  93       const work=this.getWork(input.workId);
  94       if(work.revision!==input.expectedWorkRevision)throw new LabError('STALE_WORK',`要求已是 r${work.revision}，请重读后再保存。`);
  95       if(!work.outline.some(item=>item.number===input.chapterNumber))throw new LabError('CHAPTER_OUT_OF_SCOPE','本章不在当前已确认的大纲中。');
  96       const current=this.findChapter(work.id,input.chapterNumber);
  97       if((current?.revision??0)!==input.expectedChapterRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current?.revision??0}，请重读后合并。`);
  98       const bases=[...input.expectedPreviousRevisions].sort((a,b)=>a.number-b.number);
  99       if(bases.length!==input.chapterNumber-1||bases.some((item,index)=>item.number!==index+1))throw new LabError('PREVIOUS_BASES_REQUIRED','需要逐项提供前面全部章节的当前修订。');
 100       for(const base of bases){
 101         const previous=this.findChapter(work.id,base.number);
 102         if(!previous)throw new LabError('PREVIOUS_CHAPTER_MISSING',`第 ${base.number} 章尚未保存。`);
 103         if(previous.revision!==base.revision)throw new LabError('STALE_PREVIOUS',`第 ${base.number} 章已经是 r${previous.revision}，请读取当前正文后再续写。`);
 104       }
 105       const task=taskId?this.getTask(taskId):null;
 106       if(task&&(task.workId!==work.id||task.chapterNumber!==input.chapterNumber))throw new LabError('TASK_MISMATCH','任务与本章不一致。');
 107       const chapter:Chapter={workId:work.id,number:input.chapterNumber,revision:(current?.revision??0)+1,title:input.title,body:input.body,status:'draft',workRevision:work.revision,origin,taskId,threadId:task?.threadId??null,updatedAt:new Date().toISOString(),previousRevisions:bases,reviewNote:null};
 108       return this.persistChapter(chapter);
 109     });
 110   }
 111   reviseExcerpt(scope:ApprovedExcerpt,replacement:string,origin:'human'|'agent',taskId:string|null=null):Chapter{
 112     const current=this.getChapter(scope.workId,scope.chapterNumber);
 113     if(!current)throw new LabError('CHAPTER_NOT_FOUND','还没有该章正文，不能局部修改。');
 114     if(current.revision!==scope.expectedChapterRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current.revision}，请重读后重新选定范围。`);
 115     if(scope.end>current.body.length||current.body.slice(scope.start,scope.end)!==scope.originalText)throw new LabError('EXCERPT_MISMATCH','当前正文与人工选区不一致，请重读后重新选定范围。');
 116     // UTF-16 选区外沿用当前原文，事务内的修订检查仍由同一保存函数承担。
 117     return this.saveDraft({...scope,title:current.title,body:current.body.slice(0,scope.start)+replacement+current.body.slice(scope.end)},origin,taskId);
 118   }
 119   adopt(workId:string,number:number,expectedRevision:number,note:string):Chapter{
 120     return this.transaction(()=>{
 121       const work=this.getWork(workId);
 122       const current=this.findChapter(work.id,number);
 123       if(!current)throw new LabError('CHAPTER_NOT_FOUND','还没有该章正文。');
 124       if(current.revision!==expectedRevision)throw new LabError('STALE_CHAPTER',`正文已是 r${current.revision}，不能采用旧版本。`);
 125       return this.persistChapter({...current,revision:current.revision+1,status:'adopted',origin:'human',reviewNote:note,updatedAt:new Date().toISOString()});
 126     });
 127   }
 128   exportWork(id:string){
 129     const work=this.getWork(id);
 130     const rows=this.db.prepare('SELECT content FROM chapters WHERE work_id=? ORDER BY number').all(id);
 131     const chapters=rows.map(row=>JSON.parse(row.content as string) as Chapter);
 132     const details=chapters.map(chapter=>{
 133       if(chapter.number>1)assert(chapter.previousRevisions,'连续章节缺少保存时的前文基线');
 134       const previousChanged=(chapter.previousRevisions??[]).some(base=>this.findChapter(id,base.number)?.revision!==base.revision);
 135       return {number:chapter.number,revision:chapter.revision,status:chapter.status,workRevision:chapter.workRevision,previousRevisions:chapter.previousRevisions??[],reviewNote:chapter.reviewNote??null,basisCurrent:chapter.workRevision===work.revision&&!previousChanged};
 136     });
 137     const text=`# ${work.title}\n\n用途：${work.purpose}\n\n`+chapters.map((chapter,index)=>`## 第 ${chapter.number} 章 ${chapter.title}\n\n状态：${chapter.status}，正文 r${chapter.revision}；${details[index].basisCurrent?'资料基线一致，品质仍需人判断':'资料有变动，需重新核对'}。\n\n${chapter.reviewNote?`采用说明：${chapter.reviewNote}\n\n`:''}${chapter.body}\n`).join('\n');
 138     return {workId:id,workRevision:work.revision,expectedChapters:work.outline.length,savedChapters:chapters.length,allOutlineChaptersSaved:chapters.length===work.outline.length&&chapters.every((chapter,index)=>chapter.number===index+1),chapters:details,text};
 139   }
 140   createTask(input:Pick<Task,'id'|'workId'|'chapterNumber'|'codeVersion'>):Task{
 141     const work=this.getWork(input.workId);
 142     if(!work.outline.some(item=>item.number===input.chapterNumber))throw new LabError('CHAPTER_OUT_OF_SCOPE','任务章节不在大纲中。');
 143     const now=new Date().toISOString();
 144     const task:Task={...input,threadId:null,state:'created',createdAt:now,updatedAt:now,error:null,usage:null};
 145     this.db.prepare('INSERT INTO tasks VALUES(?,?)').run(task.id,JSON.stringify(task));return task;
 146   }
 147   getTask(id:string):Task{
 148     const row=this.db.prepare('SELECT content FROM tasks WHERE id=?').get(id);
 149     if(!row)throw new LabError('TASK_NOT_FOUND','任务记录不存在。');return JSON.parse(row.content as string);
 150   }
 151   updateTask(id:string,change:Partial<Pick<Task,'threadId'|'state'|'error'|'usage'>>):Task{
 152     const task={...this.getTask(id),...change,updatedAt:new Date().toISOString()};
 153     this.db.prepare('UPDATE tasks SET content=? WHERE id=?').run(JSON.stringify(task),id);return task;
 154   }
 155 }
